using System.Threading.Channels;
namespace Charker;
internal static class CuktechTests {
 static void Check(bool okay){if(!okay)throw new Exception("CUKTECH regression check failed");}
 static void Reject(Action action){try{action();}catch{return;}throw new Exception("Expected rejection");}
 static byte[] H(string value)=>CuktechProtocol.Hex(value.Replace(" ",""));
 public static void Register(Action<string,Action> test){test("Xiaomi QR approval imports only 10 Ultra tokens without exposing credentials",XiaomiCloudTests.Run);
  test("A cached saved CUKTECH device opens without starting discovery",()=>{var expected=new object();int scanned=0;var actual=CuktechDeviceOpening.Resolve(_=>Task.FromResult<object?>(expected),_=>{scanned++;return Task.FromResult(1);},(type,ct)=>throw new Exception("Unexpected rediscovery open"),CancellationToken.None).GetAwaiter().GetResult();Check(ReferenceEquals(expected,actual)&&scanned==0);});
  test("A missing Windows LE cache triggers discovery and uses the observed address type",()=>{var expected=new object();int scans=0,used=-1;var actual=CuktechDeviceOpening.Resolve<object>(_=>Task.FromResult<object?>(null),_=>{scans++;return Task.FromResult(2);},(type,ct)=>{used=type;return Task.FromResult<object?>(expected);},CancellationToken.None).GetAwaiter().GetResult();Check(ReferenceEquals(actual,expected)&&scans==1&&used==2);});
  test("Delayed Windows cache population is retried only within the bounded open sequence",()=>{int opens=0;var pauses=new List<double>();var expected=new object();var actual=CuktechDeviceOpening.Resolve<object>(_=>Task.FromResult<object?>(null),_=>Task.FromResult(1),(type,ct)=>Task.FromResult(++opens==3?expected:null),CancellationToken.None,(pause,ct)=>{pauses.Add(pause.TotalMilliseconds);return Task.CompletedTask;}).GetAwaiter().GetResult();Check(actual==expected&&opens==3&&pauses.SequenceEqual(new[]{250d,500d}));});
  test("A discovered device that remains unavailable stops after three opens",()=>{int scans=0,opens=0;bool stopped=false;try{CuktechDeviceOpening.Resolve<object>(_=>Task.FromResult<object?>(null),_=>{scans++;return Task.FromResult(1);},(type,ct)=>{opens++;return Task.FromResult<object?>(null);},CancellationToken.None,(pause,ct)=>Task.CompletedTask).GetAwaiter().GetResult();}catch(IOException e){stopped=e.Message.Contains("Windows");}Check(stopped&&scans==1&&opens==3);});
  test("Discovery failures preserve their cause without attempting authentication",()=>{int opens=0;bool original=false;try{CuktechDeviceOpening.Resolve<object>(_=>Task.FromResult<object?>(null),_=>Task.FromException<int>(new IOException("Discovery unavailable")),(type,ct)=>{opens++;return Task.FromResult<object?>(new());},CancellationToken.None).GetAwaiter().GetResult();}catch(IOException e){original=e.Message=="Discovery unavailable";}Check(original&&opens==0);});
  test("Cancelling during rediscovery cannot open a device after disconnect",()=>{using var cancel=new CancellationTokenSource();var pending=new TaskCompletionSource<int>(TaskCreationOptions.RunContinuationsAsynchronously);int opened=0;var task=CuktechDeviceOpening.Resolve<object>(_=>Task.FromResult<object?>(null),ct=>pending.Task.WaitAsync(ct),(type,ct)=>{opened++;return Task.FromResult<object?>(new());},cancel.Token);cancel.Cancel();bool cancelled=false;try{task.GetAwaiter().GetResult();}catch(OperationCanceledException){cancelled=true;}pending.TrySetResult(1);Check(cancelled&&opened==0);});
  test("An already cancelled connection touches neither Windows cache nor discovery",()=>{using var cancel=new CancellationTokenSource();cancel.Cancel();int touched=0;bool cancelled=false;try{CuktechDeviceOpening.Resolve<object>(_=>{touched++;return Task.FromResult<object?>(new());},_=>{touched++;return Task.FromResult(1);},(type,ct)=>{touched++;return Task.FromResult<object?>(new());},cancel.Token).GetAwaiter().GetResult();}catch(OperationCanceledException){cancelled=true;}Check(cancelled&&touched==0);});
  test("An existing CUKTECH link is released and rediscovered before any new authentication",()=>{var old=new object();var fresh=new object();var order=new List<string>();var result=CuktechDeviceOpening.Resolve<object>(_=>Task.FromResult<object?>(old),_=>{order.Add("discover");return Task.FromResult(1);},(type,ct)=>{order.Add("open");return Task.FromResult<object?>(fresh);},CancellationToken.None,requiresRediscovery:d=>ReferenceEquals(d,old),releaseCached:d=>order.Add("release")).GetAwaiter().GetResult();Check(result==fresh&&order.SequenceEqual(new[]{"release","discover","open"}));});
  test("Cancelling stale-link recovery releases its old object without opening a new session",()=>{using var cancel=new CancellationTokenSource();int released=0,opens=0;bool cancelled=false;try{CuktechDeviceOpening.Resolve<object>(_=>Task.FromResult<object?>(new()),ct=>Task.FromCanceled<int>(cancel.Token),(type,ct)=>{opens++;return Task.FromResult<object?>(new());},cancel.Token,requiresRediscovery:_=>true,releaseCached:_=>{released++;cancel.Cancel();}).GetAwaiter().GetResult();}catch(OperationCanceledException){cancelled=true;}Check(cancelled&&released==1&&opens==0);});
  test("Widget stages at two and five minutes for independently sampled devices",()=>{
   var t=DateTimeOffset.UtcNow;
   var history=new PowerHistory();
   foreach(var model in new[]{"A2687","A2345","AD1204U"}){
    var d=DeviceState.Empty(model);d.Connected=true;d.Updated=t;d.Ports[0].Power=8;
    history.Record(d,t);
    WidgetCardMode At(double seconds)=>WidgetVisibility.Mode(d.Connected,history.LastWidgetLoad(d),t.AddSeconds(seconds));
    Check(At(119.999)==WidgetCardMode.Expanded && At(120)==WidgetCardMode.Compact);
    Check(At(299.999)==WidgetCardMode.Compact && At(300)==WidgetCardMode.Hidden);
    d.Updated=null;history.Record(d,t.AddSeconds(125));Check(At(125)==WidgetCardMode.Compact);
    d.Connected=false;history.Record(d,t.AddSeconds(126));Check(At(126)==WidgetCardMode.Hidden);
   }
  });
  test("Widget waiting row ignores pulses and expands on resumed charging",()=>{
   foreach(var model in new[]{"A2687","A2345","AD1204U"}){
    var t=DateTimeOffset.UtcNow;var history=new PowerHistory();var d=DeviceState.Empty(model);d.Connected=true;
    WidgetCardMode Feed(int seconds,double watts){var at=t.AddSeconds(seconds);d.Updated=at;d.Ports[0].Power=watts;history.Record(d,at);return WidgetVisibility.Mode(true,history.LastWidgetLoad(d),at);}
    Check(Feed(0,.1)==WidgetCardMode.Hidden && Feed(1,.5)==WidgetCardMode.Hidden);
    Check(Feed(2,8)==WidgetCardMode.Expanded && Feed(3,0)==WidgetCardMode.Expanded);
    Check(Feed(125,.5)==WidgetCardMode.Compact && Feed(126,0)==WidgetCardMode.Compact);
    Check(Feed(140,10)==WidgetCardMode.Expanded && Feed(175,0)==WidgetCardMode.Expanded);
    Check(Feed(439,.1)==WidgetCardMode.Compact && Feed(440,0)==WidgetCardMode.Hidden);
   }
  });
  test("Confirmed sustained low load keeps its own deadline as proof ages out",()=>{
   var history=new PowerHistory();var t=DateTimeOffset.UtcNow;
   var first=DeviceState.Empty("A2345");var second=DeviceState.Empty("AD1204U");first.Connected=second.Connected=true;
   for(int i=0;i<=6;i++){first.Updated=t.AddSeconds(i);first.Ports[0].Power=.5;history.Record(first,first.Updated.Value);}
   second.Updated=t.AddSeconds(280);second.Ports[1].Power=2;history.Record(second,second.Updated.Value);
   var now=t.AddSeconds(305);first.Updated=now;first.Ports[0].Power=0;history.Record(first,now);
   Check(WidgetVisibility.Mode(true,history.LastWidgetLoad(first),now)==WidgetCardMode.Compact);
   Check(WidgetVisibility.Mode(true,history.LastWidgetLoad(second),now)==WidgetCardMode.Expanded);
   Check(WidgetVisibility.Mode(true,history.LastWidgetLoad(first),now.AddSeconds(1))==WidgetCardMode.Hidden);
  });
  test("MIOT length fields follow GET property count and SET value width",()=>{for(int count=1;count<=21;count++){var b=CuktechProtocol.Get(3,Enumerable.Range(1,count).ToArray());Check(b[0]==b.Length&&b[4]==2&&b[5]==count);}foreach(int size in new[]{1,2,4}){var b=CuktechProtocol.Set(4,5,1,size);Check(b[0]==b.Length&&b[4]==0);}});
