  test("A two-byte GET response cannot be confused with an equal-length push",()=>{var b=H("0f2003000301020900000002201e00");var p=CuktechProtocol.Parse(b);Check(p.Length==1&&p[0].Id==9&&p[0].Value==30);});
  test("Real-sized bulk replies and same-sequence pushes complete only the matching request",()=>{foreach(int mtu in new[]{23,247}){using var peer=new Peer(mtu){FullSnapshot=true,Interleave=mtu==23,MultiPush=true};using var mi=peer.Session();int notifications=0;var state=DeviceState.Empty("AD1204U");mi.Notification+=b=>{CuktechProtocol.Apply(state,CuktechProtocol.Parse(b));notifications++;};mi.Login(Peer.Token,()=>Task.CompletedTask).GetAwaiter().GetResult();mi.ReadProperties(1,2,3,4,5,6,7,13,15,16,19,20).GetAwaiter().GetResult();Check(state.Ports[0].Power==100&&state.Settings.ContainsKey("portMask"));mi.ReadProperties(1,2,3,4).GetAwaiter().GetResult();Check(notifications>=(mtu==23?4:2));}});
  test("Mi BLE receive window accepts bounded reordering and remains bounded",()=>{var w=new MiBleReceiveWindow();Check(w.Accept(0,[1])==MiBleReceiveWindow.Result.Fresh);Check(w.Accept(2,[2])==MiBleReceiveWindow.Result.Fresh);Check(w.Accept(1,[3])==MiBleReceiveWindow.Result.Late);for(int i=3;i<1000;i++)w.Accept(i,BitConverter.GetBytes(i));Check(w.Count==MiBleReceiveWindow.Capacity&&w.Highest==999);Check(w.Accept(1,[3])==MiBleReceiveWindow.Result.TooOld);Reject(()=>w.Accept(65536,[0]));});
  test("Mi BLE replay window ignores exact repeats but rejects counter reuse with changed contents",()=>{var w=new MiBleReceiveWindow();w.Accept(7,[1,2]);Check(w.Accept(7,[1,2])==MiBleReceiveWindow.Result.Duplicate);Reject(()=>w.Accept(7,[1,3]));});
  test("Delayed authenticated C2 notifications survive newer C1 without rolling C1 backwards",()=>{using var peer=new Peer(247);using var mi=peer.Session();var state=DeviceState.Empty("AD1204U");mi.Properties+=p=>CuktechProtocol.Apply(state,p);mi.Login(Peer.Token,()=>Task.CompletedTask).GetAwaiter().GetResult();peer.Inject(3,Reading(1,8));Eventually(()=>state.Ports[0].Power==8);peer.Inject(2,Reading(2,5));Eventually(()=>state.Ports[1].Power==5);peer.Inject(5,Reading(1,12));Eventually(()=>state.Ports[0].Power==12);int late=0;mi.Trace+=t=>{if(t.Contains("分类 Late"))Interlocked.Increment(ref late);};peer.Inject(4,Reading(1,3));Eventually(()=>Volatile.Read(ref late)>0);Check(state.Ports[0].Power==12&&state.Ports[1].Power==5);});
  test("Repeated authenticated BLE notifications are acknowledged without duplicate samples or disconnection",()=>{using var peer=new Peer(247);using var mi=peer.Session();int updates=0;Exception? failed=null;mi.Properties+=_=>Interlocked.Increment(ref updates);mi.Failed+=e=>failed=e;mi.Login(Peer.Token,()=>Task.CompletedTask).GetAwaiter().GetResult();int acks=peer.Acks;var b=Reading(1,8);peer.Inject(1,b);peer.Inject(1,b);Eventually(()=>peer.Acks>=acks+2);Check(updates==1&&failed==null);mi.ReadProperties(1).GetAwaiter().GetResult();Check(updates==2);});
  test("Out-of-order support never accepts a damaged AES-CCM message",()=>{using var peer=new Peer(247);using var mi=peer.Session();int updates=0;var failed=new TaskCompletionSource<Exception>(TaskCreationOptions.RunContinuationsAsynchronously);mi.Properties+=_=>updates++;mi.Failed+=e=>failed.TrySetResult(e);mi.Login(Peer.Token,()=>Task.CompletedTask).GetAwaiter().GetResult();peer.Inject(2,Reading(1,8),corrupt:true);Check(failed.Task.Wait(TimeSpan.FromSeconds(3))&&failed.Task.Result is CryptographicException&&updates==0);});
