  test("Mi BLE HKDF and HMAC match independent Node crypto vectors",()=>{var k=CuktechProtocol.Derive(H("000102030405060708090a0b"),H("000102030405060708090a0b0c0d0e0f"),H("101112131415161718191a1b1c1d1e1f"));Check(Convert.ToHexString(k).Equals("18eea5008b0cee3744c215c7cd9ead268670b5056f4a71ffd1d4ea419e3c84be2a03093f8eb73a36cf1abcf9d346e44edd6594b602b018ac98d72cca94609c2a",StringComparison.OrdinalIgnoreCase));Check(Convert.ToHexString(HMACSHA256.HashData(k[..16],H("101112131415161718191a1b1c1d1e1f000102030405060708090a0b0c0d0e0f"))).Equals("99936f1c9a0a1dcda373d014172ccbf46564268d2b56c02f0ef3ec6ead544333",StringComparison.OrdinalIgnoreCase));var cipher=CuktechProtocol.Encrypt(k[16..32],k[36..40],2,H("05200200f0"));Check(cipher.SequenceEqual(H("f8fe1134e337282136")));Check(CuktechProtocol.Decrypt(k[16..32],k[36..40],2,cipher).SequenceEqual(H("05200200f0")));cipher[0]^=1;Reject(()=>CuktechProtocol.Decrypt(k[16..32],k[36..40],2,cipher));Reject(()=>CuktechProtocol.Nonce(k[36..40],65536));});
  test("MIOT GET and SET match published capture byte vectors",()=>{Check(CuktechProtocol.Get(11,[1,2,15]).SequenceEqual(H("0f 20 0b 00 02 03 02 01 00 02 02 00 02 0f 00")));Check(CuktechProtocol.Set(13,15,1,boolean:true).SequenceEqual(H("0c 20 0d 00 00 01 02 0f 00 01 00 01")));Check(CuktechProtocol.Set(2,5,3).SequenceEqual(H("0c 20 02 00 00 01 02 05 00 01 10 03")));});
  test("MIOT notification and bulk reads decode active bitfields and idle power",()=>{var s=DeviceState.Empty("AD1204U");var b=H("1820020004020201000450110332c8020200045000600132");CuktechProtocol.Apply(s,CuktechProtocol.Parse(b));Check(s.Ports[0].Power==100&&s.Ports[0].Voltage==20&&s.Ports[0].Current==5);Check(s.Ports[1].Power==0);Check(s.Ports[0].Protocol=="USB PD");Reject(()=>CuktechProtocol.Parse(b[..^1]));});
