 }
 static void Eventually(Func<bool> f){if(!SpinWait.SpinUntil(f,3000))throw new Exception("Timed out waiting for Mi BLE test event");}
 static byte[] Reading(int id,int watts)=>[15,0x20,7,0,4,1,2,(byte)id,0,4,0x50,1,3,(byte)(watts*2),50];
 static byte[] Bulk(ushort sequence,int[] ids){var bytes=new List<byte>{0,0x20,(byte)sequence,(byte)(sequence>>8),3,(byte)ids.Length};foreach(int id in ids){bytes.AddRange([2,(byte)id,(byte)(id>>8),0,0]);if(id<=4){bytes.AddRange([4,0x50]);bytes.AddRange(id==1?new byte[]{1,3,50,200}:new byte[]{0,0,0,50});}else bytes.AddRange([1,(byte)(id is 15 or 19 or 20?0:0x10),(byte)(id==16?15:1)]);}bytes[0]=(byte)(bytes.Count&255);return bytes.ToArray();}
 sealed class Peer : IDisposable {
  public static readonly byte[] Token=H("000102030405060708090a0b");readonly Dictionary<ushort,Channel<byte[]>> q=new(){[0x10]=Channel.CreateUnbounded<byte[]>(),[0x19]=Channel.CreateUnbounded<byte[]>(),[0x1a]=Channel.CreateUnbounded<byte[]>(),[0x1b]=Channel.CreateUnbounded<byte[]>()};readonly CancellationTokenSource ct=new();readonly int mtu;byte[] keys=[],app=[];readonly byte[] dev=H("101112131415161718191a1b1c1d1e1f");int authCount,authCode,sendCount,sendCounter,deviceCounter,pushCounter;readonly List<byte> authBytes=[],sendBytes=[];readonly Queue<byte[]> parts=new();public readonly List<int> AppCounters=[];public bool FailNextCipher;public int Acks;public bool AppProofVerified,Interleave,Stall,FullSnapshot,MultiPush;ushort pushSequence;
  public Peer(int mtu){this.mtu=mtu;}
  public MiBleSession Session()=>new(Write,(id,cancel)=>q[id].Reader.ReadAsync(cancel).AsTask(),()=>mtu,ct.Token);
  public void Inject(int counter,byte[] plain,bool corrupt=false){var cipher=CuktechProtocol.Encrypt(keys[..16],keys[32..36],counter,plain);if(corrupt)cipher[0]^=1;deviceCounter=Math.Max(deviceCounter,counter+1);Put(0x1b,new byte[]{0,0,2,0,(byte)counter,(byte)(counter>>8)}.Concat(cipher).ToArray());}
  void Put(ushort id,byte[] b)=>q[id].Writer.TryWrite(b);
  Task Write(ushort id,byte[] b,CancellationToken cancel){cancel.ThrowIfCancellationRequested();if(id==0x10&&b.SequenceEqual(new byte[]{0xa4})){Put(0x19,[0,0,4,7]);Put(0x19,[0,0,4,8]);}
   else if(id==0x19&&b.Length==6&&b[0]==0&&b[2]==0){authCode=b[3];authCount=BitConverter.ToUInt16(b,4);authBytes.Clear();Put(id,[0,0,1,1]);}
   else if(id==0x19&&b.Length>=2&&BitConverter.ToUInt16(b)>0){authBytes.AddRange(b[2..]);if(--authCount==0){Put(id,[0,0,1,0]);if(authCode==0x0b){app=authBytes.ToArray();keys=CuktechProtocol.Derive(Token,app,dev);Put(id,new byte[]{0,0,2,0x0d}.Concat(dev).ToArray());Put(id,new byte[]{0,0,2,0x0c}.Concat(HMACSHA256.HashData(keys[..16],dev.Concat(app).ToArray())).ToArray());}else{AppProofVerified=authBytes.SequenceEqual(HMACSHA256.HashData(keys[16..32],app.Concat(dev).ToArray()));if(!AppProofVerified)throw new Exception("Bad app proof");Put(0x10,[0x21,0,0,0]);}}}
   else if(id==0x1a&&b.Length==6&&b[0]==0&&b[2]==0){sendCount=BitConverter.ToUInt16(b,4);sendBytes.Clear();if(!Stall)Put(id,[0,0,1,1]);}
